package br.com.conectatea.crianca.domain; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="historico_crianca") public class HistoricoCrianca{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="crianca_id")private Long crianca;@Column(name="autor_usuario_id")private Long autor;private String tipo;@Column(name="estado_anterior")private String anterior;@Column(name="estado_novo")private String novo;private String motivo;@Column(name="criado_em")private Instant criado=Instant.now();protected HistoricoCrianca(){}public HistoricoCrianca(Long c,Long a,String t,String old,String next,String m){crianca=c;autor=a;tipo=t;anterior=old;novo=next;motivo=m;}}
